interface TypingEngineProps {
  targetText: string;
  onSessionComplete: (session: TypingSession, metrics: TypingMetrics) => void;
  duration?: number;
  enabled?: boolean;
}

interface TypingSession {
  id: string;
  userId: string;
  targetText: string;
  typedText: string;
  startTime: Date;
  endTime?: Date;
  duration: number;
  isPaused: boolean;
  currentCharIndex: number;
}

interface TimerEvents {
  onStart: () => void;
  onPause: () => void;
  onResume: () => void;
  onComplete: () => void;
}
